/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
r=Path('.')
print('PROGRAMS')
for c in ['report','x1','x1sim']:
 for p in sorted((r/'programs/algol-60'/c).glob('P1[12]*')): print(p)
print('RECORD COUNTS')
for c in ['report','x1','x1sim']:
 for p in sorted((r/'results/algol-60'/c).glob('P1[12]*')):
  for sub in ['raw','raw-rerun-m2']:
   fs=list((p/sub).glob('*'))
   if fs: print(c,p.name,sub,len(fs),sum(f.stat().st_size for f in fs))
print('LOGS')
for p in sorted((r/'results/algol-60/logs').glob('*')): print(p)
PY"

